class Inventory:
    def __init__(self):
        self.items = {}

    def add(self, name, amount):
        self.items[name] = self.items.get(name, 0) + amount

    def remove(self, name, amount):
        if self.items.get(name, 0) < amount:
            raise ValueError(name)
        self.items[name] -= amount

    def report(self):
        return [(name, n) for name, n in sorted(self.items.items()) if n > 0]


inventory = Inventory()
while True:
    parts = input().split()
    if parts[0] == "end":
        break
    name, amount = parts[1], int(parts[2])
    if parts[0] == "in":
        inventory.add(name, amount)
    elif parts[0] == "out":
        try:
            inventory.remove(name, amount)
        except ValueError:
            print(f"출고 실패: {name}")

remaining = inventory.report()
if remaining:
    for name, n in remaining:
        print(name, n)
else:
    print("재고 없음")
